local function Money(copper)
    if not copper then return "|cff808080--|r" end
    local sign = copper < 0 and "-" or ""
    copper = math.floor(math.abs(copper) + 0.5)
    local g, s, c = math.floor(copper / 10000), math.floor(copper / 100) % 100, copper % 100
    if g > 0 then
        return format("%s%d|cffffd700g|r %02d|cffc7c7cfs|r", sign, g, s)
    elseif s > 0 then
        return format("%s%d|cffc7c7cfs|r %02d|cffeda55fc|r", sign, s, c)
    end
    return format("%s%d|cffeda55fc|r", sign, c)
end

local function ItemName(itemID)
    return (C_Item.GetItemNameByID and C_Item.GetItemNameByID(itemID)) or ("item:" .. itemID)
end

local function Age(t)
    if not t then return "never" end
    local s = time() - t
    if s < 90 then return "just now" end
    if s < 5400 then return format("%d min ago", math.floor(s / 60)) end
    if s < 172800 then return format("%d h ago", math.floor(s / 3600)) end
    return format("%d days ago", math.floor(s / 86400))
end

local function CaptureRecipes()
    local TS = C_TradeSkillUI
    if not TS.IsTradeSkillReady() then return end
    if (TS.IsTradeSkillLinked and TS.IsTradeSkillLinked())
        or (TS.IsTradeSkillGuild and TS.IsTradeSkillGuild())
        or (TS.IsNPCCrafting and TS.IsNPCCrafting()) then
        return
    end
    local prof = TS.GetBaseProfessionInfo()
    if not prof then return end
    if not ((ALCHEMY and prof.profession == ALCHEMY)
        or prof.professionID == ALCHEMY_SKILL_LINE
        or prof.parentProfessionID == ALCHEMY_SKILL_LINE) then
        return
    end

    local ids = (TS.GetAllRecipeIDs and TS.GetAllRecipeIDs()) or TS.GetFilteredRecipeIDs()
    local recipes, count = {}, 0
    for _, recipeID in ipairs(ids or {}) do
        local info = TS.GetRecipeInfo(recipeID)
        if info and info.learned then
            local schematic = TS.GetRecipeSchematic(recipeID, false)
            if schematic and schematic.outputItemID then
                local slots = {}
                for _, slot in ipairs(schematic.reagentSlotSchematics) do
                    if slot.required and slot.reagentType == BASIC_REAGENT then
                        local items = {}
                        for _, reagent in ipairs(slot.reagents) do
                            if reagent.itemID then items[#items + 1] = reagent.itemID end
                        end
                        if #items > 0 then
                            slots[#slots + 1] = { qty = slot.quantityRequired, items = items }
                        end
                    end
                end
                recipes[recipeID] = {
                    name = schematic.name,
                    out = schematic.outputItemID,
                    qty = math.max(1, (schematic.quantityMin + schematic.quantityMax) / 2),
                    slots = slots,
                }
                count = count + 1
            end
        end
    end
    if count > 0 then
        db.recipes = recipes
        if window and window:IsShown() then Refresh() end
    end
end

local byOutput = {}

local function BuyPrice(itemID)
    local ah, vendor = db.prices[itemID], db.vendor[itemID]
    if vendor and (not ah or vendor <= ah) then return vendor, "vendor" end
    if ah then return ah, "AH" end
end

local CraftCost

local function UnitCost(itemID, seen)
    local price, source = BuyPrice(itemID)
    local recipe = byOutput[itemID]
    if recipe and not seen[itemID] then
        seen[itemID] = true
        local cost = CraftCost(recipe, seen)
        seen[itemID] = nil
        if cost and (not price or cost / recipe.qty < price) then
            price, source = cost / recipe.qty, "craft"
        end
    end
    return price, source
end

local function SlotBest(slot, seen)
    local bestItem, bestPrice, bestSource
    for _, itemID in ipairs(slot.items) do
        local price, source = UnitCost(itemID, seen)
        if price and (not bestPrice or price < bestPrice) then
            bestItem, bestPrice, bestSource = itemID, price, source
        end
    end
    return bestItem or slot.items[1], bestPrice, bestSource
end

function CraftCost(recipe, seen)
    local total = 0
    for _, slot in ipairs(recipe.slots) do
        local _, price = SlotBest(slot, seen)
        if not price then return nil end
        total = total + price * slot.qty
    end
    return total
end

local function BuildRows()
    wipe(byOutput)
    for _, recipe in pairs(db.recipes) do byOutput[recipe.out] = recipe end

    local rows = {}
    for _, recipe in pairs(db.recipes) do
        local cost = CraftCost(recipe, { [recipe.out] = true })
        local unit = db.prices[recipe.out]
        local revenue = unit and unit * recipe.qty * (1 - AH_CUT)
        rows[#rows + 1] = {
            recipe = recipe,
            cost = cost,
            revenue = revenue,
            profit = cost and revenue and (revenue - cost),
        }
    end
    table.sort(rows, function(a, b)
        if a.profit and b.profit then
            if a.profit ~= b.profit then return a.profit > b.profit end
        elseif a.profit or b.profit then
            return a.profit ~= nil
        end
        return a.recipe.name < b.recipe.name
    end)
    return rows
end

local HERB_CLASS, HERB_SUBCLASS = 7, 9
local ItemClass

local function BagCounts()
    local counts = {}
    local C = C_Container
    if not (C and C.GetContainerNumSlots and C.GetContainerItemInfo) then return counts end
    for bag = 0, (NUM_TOTAL_EQUIPPED_BAG_SLOTS or NUM_BAG_SLOTS or 4) do
        for slot = 1, C.GetContainerNumSlots(bag) or 0 do
            local info = C.GetContainerItemInfo(bag, slot)
            if info and info.itemID then
                counts[info.itemID] = (counts[info.itemID] or 0) + (info.stackCount or 1)
            end
        end
    end
    return counts
end

-- Bag items worth a verdict: herbs, plus anything a known recipe uses.
-- Vendor-bought mats (vials) are left out: they are bought as needed, never sold.
local function BagMaterials()
    local reagents = {}
    for _, recipe in pairs(db.recipes) do
        for _, slot in ipairs(recipe.slots) do
            for _, itemID in ipairs(slot.items) do reagents[itemID] = true end
        end
    end
    local held = {}
    for itemID, count in pairs(BagCounts()) do
        if not db.vendor[itemID] then
            local classID, subClassID = ItemClass(itemID)
            if reagents[itemID] or (classID == HERB_CLASS and subClassID == HERB_SUBCLASS) then
                held[itemID] = count
            end
        end
    end
    return held
end

local function RawValue(itemID)
    local price = db.prices[itemID]
    return price and price * (1 - AH_CUT) or 0
end

-- One craft of a recipe from what is left in the bags. Vendor mats are bought,
-- everything else has to be held. Gain is what brewing earns over listing the
-- same herbs raw.
local function BagCraft(recipe, left)
    local unit = db.prices[recipe.out]
    if not unit then return end
    local need, buys, raw, bought = {}, {}, 0, 0
    for _, slot in ipairs(recipe.slots) do
        local bestItem, bestCost, bestHeld
        for _, itemID in ipairs(slot.items) do
            local cost, isHeld
            if (left[itemID] or 0) >= (need[itemID] or 0) + slot.qty then
                cost, isHeld = RawValue(itemID), true
            elseif db.vendor[itemID] then
                cost = db.vendor[itemID]
            end
            if cost and (not bestCost or cost < bestCost) then
                bestItem, bestCost, bestHeld = itemID, cost, isHeld
            end
        end
        if not bestItem then return end
        if bestHeld then
            need[bestItem] = (need[bestItem] or 0) + slot.qty
            raw = raw + bestCost * slot.qty
        else
            buys[bestItem] = (buys[bestItem] or 0) + slot.qty
            bought = bought + bestCost * slot.qty
        end
    end
    local crafts
    for itemID, qty in pairs(need) do
        local n = math.floor(left[itemID] / qty)
        if not crafts or n < crafts then crafts = n end
    end
    if not crafts or crafts < 1 then return end
    local value = unit * recipe.qty * (1 - AH_CUT) - bought
    return { crafts = crafts, need = need, buys = buys, raw = raw, value = value, gain = value - raw }
end

-- Greedy: keep brewing whichever recipe beats raw herbs by the most per craft
-- until nothing does, then everything left over is a "sell" row.
local function BuildHerbRows()
    local left = BagMaterials()
    local plans, rows = {}, {}
    for _ = 1, 200 do
        local best, bestRecipe
        for _, recipe in pairs(db.recipes) do
            local option = BagCraft(recipe, left)
            if option and option.gain > 0 and (not best or option.gain > best.gain) then
                best, bestRecipe = option, recipe
            end
        end
        if not best then break end
        local plan = plans[bestRecipe]
        if not plan then
            plan = { kind = "craft", recipe = bestRecipe, crafts = 0, raw = 0, value = 0, uses = {}, buys = {} }
            plans[bestRecipe] = plan
            rows[#rows + 1] = plan
        end
        local n = best.crafts
        plan.crafts = plan.crafts + n
        plan.raw = plan.raw + best.raw * n
        plan.value = plan.value + best.value * n
        for itemID, qty in pairs(best.need) do
            plan.uses[itemID] = (plan.uses[itemID] or 0) + qty * n
            left[itemID] = left[itemID] - qty * n
        end
        for itemID, qty in pairs(best.buys) do
            plan.buys[itemID] = (plan.buys[itemID] or 0) + qty * n
        end
    end

    local totals = { brewed = 0, sold = 0, raw = 0 }
    for _, plan in ipairs(rows) do
        plan.gain = plan.value - plan.raw
        totals.brewed = totals.brewed + plan.value
        totals.raw = totals.raw + plan.raw
    end
    for itemID, count in pairs(left) do
        if count > 0 then
            local price = db.prices[itemID]
            local value = price and price * count * (1 - AH_CUT)
            rows[#rows + 1] = { kind = "sell", itemID = itemID, count = count, value = value }
            totals.sold = totals.sold + (value or 0)
            totals.raw = totals.raw + (value or 0)
        end
    end
    table.sort(rows, function(a, b)
        if a.kind ~= b.kind then return a.kind == "craft" end
        local x, y = a.gain or a.value or -1, b.gain or b.value or -1
        if x ~= y then return x > y end
        return (a.itemID or a.recipe.out) < (b.itemID or b.recipe.out)
    end)
    return rows, totals
end

local scan

local function SetStatus(text)
    if window then window.status:SetText(text) end
end

local function StopScan(finished)
    if not scan then return end
    scan.ticker:Cancel()
    scan = nil
    if finished then db.scanTime = time() end
    if window then
        window.scan:SetText("Scan")
        window.scanAll:SetEnabled(true)
        Refresh()
        if not finished then SetStatus("Scan stopped early. Some prices may be old.") end
    end
end

function ItemClass(itemID)
    local instant = (C_Item and C_Item.GetItemInfoInstant) or GetItemInfoInstant
    if not instant then return end
    local _, _, _, _, _, classID, subClassID = instant(itemID)
    return classID, subClassID
end

-- A browse returns the cheapest price of every item in a category, 50 per page,
-- so a few pages replace hundreds of single-item searches. If it fails or looks
-- wrong, every item falls back to its own search.
local function FinishBrowse(ok)
    local found = 0
    for _ in pairs(scan.found) do found = found + 1 end
    if ok and found * 4 >= scan.browseCount then
        for itemID in pairs(scan.browsing) do db.prices[itemID] = scan.found[itemID] end
    else
        for itemID in pairs(scan.browsing) do scan.queue[#scan.queue + 1] = itemID end
    end
    scan.phase, scan.waiting, scan.total = "search", false, #scan.queue
end

local function BrowseStep(now)
    if scan.waiting then
        if now - scan.sentAt > BROWSE_TIMEOUT then FinishBrowse(false) end
        return
    end
    if not C_AuctionHouse.IsThrottledMessageSystemReady() then return end
    scan.waiting, scan.sentAt = true, now
    local ok
    if scan.pages == 0 then
        ok = pcall(C_AuctionHouse.SendBrowseQuery, {
            searchString = "", sorts = SORTS, filters = {}, itemClassFilters = scan.filters,
        })
    else
        ok = pcall(C_AuctionHouse.RequestMoreBrowseResults)
    end
    if not ok then
        FinishBrowse(false)
        return
    end
    scan.pages = scan.pages + 1
    SetStatus(format("Reading the auction house, page %d ...", scan.pages))
end

local function OnBrowseResults(added)
    if not scan or scan.phase ~= "browse" or not scan.waiting then return end
    for _, entry in ipairs(added or C_AuctionHouse.GetBrowseResults() or {}) do
        local itemID, price = entry.itemKey and entry.itemKey.itemID, entry.minPrice
        if itemID and scan.browsing[itemID] and price and price > 0
            and (not scan.found[itemID] or price < scan.found[itemID]) then
            scan.found[itemID] = price
        end
    end
    scan.waiting = false
    if C_AuctionHouse.HasFullBrowseResults() then FinishBrowse(true) end
end

local function ScanStep()
    local now = GetTime()
    if scan.phase == "browse" then
        BrowseStep(now)
        return
    end
    if scan.current then
        if now - scan.sentAt < TIMEOUT then return end
        db.prices[scan.current] = nil -- no answer: treat as not for sale
        scan.current = nil
    end
    if #scan.queue == 0 then
        StopScan(true)
        return
    end
    if now - scan.lastSend < SEND_INTERVAL or not C_AuctionHouse.IsThrottledMessageSystemReady() then
        return
    end
    scan.current = table.remove(scan.queue)
    scan.sentAt, scan.lastSend = now, now
    C_AuctionHouse.SendSearchQuery(C_AuctionHouse.MakeItemKey(scan.current), SORTS, false)
    SetStatus(format("Scanning %d / %d ...", scan.total - #scan.queue, scan.total))
end

local function StartScan(all)
    if scan then
        StopScan(false)
        return
    end
    if not ahOpen then
        SetStatus("|cffff5555Open the auction house first.|r")
        return
    end
    local seen, queue = {}, {}
    local function add(itemID)
        if not seen[itemID] then
            seen[itemID] = true
            queue[#queue + 1] = itemID
        end
    end
    for _, recipe in pairs(db.recipes) do
        add(recipe.out)
        for _, slot in ipairs(recipe.slots) do
            for _, itemID in ipairs(slot.items) do add(itemID) end
        end
    end
    if all then
        for _, itemID in ipairs(SITE_ITEMS) do add(itemID) end
    end
    for itemID in pairs(BagMaterials()) do add(itemID) end
    if #queue == 0 then
        SetStatus("|cffff5555No recipes yet. Open your Alchemy window once.|r")
        return
    end
    local browsing, filters, filterSeen, single = {}, {}, {}, {}
    local canBrowse = C_AuctionHouse.SendBrowseQuery and C_AuctionHouse.HasFullBrowseResults
    for _, itemID in ipairs(queue) do
        local classID, subClassID = ItemClass(itemID)
        if canBrowse and classID then
            browsing[itemID] = true
            local key = classID .. ":" .. (subClassID or "")
            if not filterSeen[key] then
                filterSeen[key] = true
                filters[#filters + 1] = { classID = classID, subClassID = subClassID }
            end
        else
            single[#single + 1] = itemID
        end
    end
    scan = {
        queue = single, total = #single, lastSend = 0,
        phase = #filters > 0 and "browse" or "search",
        browsing = browsing, browseCount = #queue - #single, filters = filters, found = {}, pages = 0,
    }
    window.scanAll:SetEnabled(false)
    scan.ticker = C_Timer.NewTicker(0.1, ScanStep)
    window.scan:SetText("Stop")
end

local function OnCommodityResults(itemID)
    if not scan or itemID ~= scan.current then return end
    local price
    if C_AuctionHouse.GetNumCommoditySearchResults(itemID) > 0 then
        local info = C_AuctionHouse.GetCommoditySearchResultInfo(itemID, 1)
        price = info and info.unitPrice
    end
    db.prices[itemID] = price
    scan.current = nil
end

local function OnItemResults(itemKey)
    if not scan or not itemKey or itemKey.itemID ~= scan.current then return end
    local price
    for i = 1, C_AuctionHouse.GetNumItemSearchResults(itemKey) do
        local info = C_AuctionHouse.GetItemSearchResultInfo(itemKey, i)
        local buyout = info and info.buyoutAmount
        if buyout and buyout > 0 and (not price or buyout < price) then price = buyout end
    end
    db.prices[itemKey.itemID] = price
    scan.current = nil
end

local function AuctionatorPrice(itemID)
    local api = Auctionator and Auctionator.API and Auctionator.API.v1
    if not (api and api.GetAuctionPriceByItemID) then return end
    local ok, price = pcall(api.GetAuctionPriceByItemID, "WhatToBrew", itemID)
    if ok and type(price) == "number" and price > 0 then return price end
end

-- WTB1^t=<scan time>^r=<name>~<itemID>;...^p=<itemID>:<copper>,...^a=...^v=...
-- p = own scan, a = Auctionator's last seen price, v = vendor prices
local function BuildExport()
    local wanted, order = {}, {}
    local function want(itemID)
        if not wanted[itemID] then
            wanted[itemID] = true
            order[#order + 1] = itemID
        end
    end
    local names = {}
    for _, recipe in pairs(db.recipes) do
        names[#names + 1] = recipe.name:gsub("[%^;~]", " ") .. "~" .. recipe.out
        want(recipe.out)
        for _, slot in ipairs(recipe.slots) do
            for _, itemID in ipairs(slot.items) do want(itemID) end
        end
    end
    for _, itemID in ipairs(SITE_ITEMS) do want(itemID) end
    table.sort(names)
    table.sort(order)

    local own, other, vendor = {}, {}, {}
    for _, itemID in ipairs(order) do
        local price = db.prices[itemID]
        if price then
            own[#own + 1] = format("%d:%d", itemID, math.floor(price + 0.5))
        else
            price = AuctionatorPrice(itemID)
            if price then other[#other + 1] = format("%d:%d", itemID, math.floor(price + 0.5)) end
        end
        local v = db.vendor[itemID]
        if v and v >= 1 then vendor[#vendor + 1] = format("%d:%d", itemID, math.floor(v + 0.5)) end
    end
    return table.concat({
        "WTB1",
        "t=" .. (db.scanTime or 0),
        "r=" .. table.concat(names, ";"),
        "p=" .. table.concat(own, ","),
        "a=" .. table.concat(other, ","),
        "v=" .. table.concat(vendor, ","),
    }, "^"), #own, #other
end

local exportFrame

local function ShowExport()
    if not exportFrame then
        local f = CreateFrame("Frame", "WhatToBrewExportFrame", UIParent, "BasicFrameTemplateWithInset")
        f:SetSize(460, 130)
        f:SetPoint("CENTER", 0, 120)
        f:SetFrameStrata("DIALOG")
        tinsert(UISpecialFrames, "WhatToBrewExportFrame")
        if f.TitleText then f.TitleText:SetText("What To Brew export") end

        f.help = f:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
        f.help:SetPoint("TOPLEFT", 14, -34)
        f.help:SetPoint("RIGHT", f, "RIGHT", -14, 0)
        f.help:SetJustifyH("LEFT")

        local box = CreateFrame("EditBox", nil, f, "InputBoxTemplate")
        box:SetPoint("BOTTOMLEFT", 20, 18)
        box:SetPoint("BOTTOMRIGHT", -16, 18)
        box:SetHeight(22)
        box:SetAutoFocus(false)
        box:SetMaxLetters(0)
        box:SetScript("OnEscapePressed", function() f:Hide() end)
        box:SetScript("OnEditFocusGained", function(self) self:HighlightText() end)
        box:SetScript("OnTextChanged", function(self, userInput)
            if userInput and f.text then
                self:SetText(f.text)
                self:HighlightText()
            end
        end)
        f.box = box
        exportFrame = f
    end
    local text, own, other = BuildExport()
    exportFrame.text = text
    exportFrame.help:SetText(format(
        "Press Ctrl+C, then paste into zakpruitt.github.io/what-to-brew\n%d scanned prices%s. Scanned %s.",
        own, other > 0 and format(" plus %d from Auctionator", other) or "", Age(db.scanTime)))
    exportFrame.box:SetText(text)
    exportFrame:Show()
    exportFrame.box:SetFocus()
    exportFrame.box:HighlightText()
end

local function LearnVendorPrices()
    if not (GetMerchantNumItems and GetMerchantItemID and C_MerchantFrame and C_MerchantFrame.GetItemInfo) then return end
    for i = 1, GetMerchantNumItems() do
        local itemID = GetMerchantItemID(i)
        local info = C_MerchantFrame.GetItemInfo(i)
        if itemID and info and info.price and info.price > 0 and not info.hasExtendedCost then
            db.vendor[itemID] = info.price / math.max(1, info.stackCount or 1)
        end
    end
end

local ROW_HEIGHT = 18
local COLUMNS = {
    { key = "name",   title = "Recipe",         herbs = "Do this",         width = 210, justify = "LEFT" },
    { key = "cost",   title = "Reagent cost",   herbs = "Sold raw (-5%)",  width = 95,  justify = "RIGHT" },
    { key = "sell",   title = "Sells (-5%)",    herbs = "Brewed (-5%)",    width = 95,  justify = "RIGHT" },
    { key = "profit", title = "Profit / craft", herbs = "Extra from brew", width = 100, justify = "RIGHT" },
    { key = "margin", title = "Margin",         herbs = "",                width = 55,  justify = "RIGHT" },
}

local function MakeCells(parent, font)
    local cells, x = {}, 4
    for _, col in ipairs(COLUMNS) do
        local fs = parent:CreateFontString(nil, "OVERLAY", font)
        fs:SetPoint("LEFT", parent, "LEFT", x, 0)
        fs:SetWidth(col.width)
        fs:SetJustifyH(col.justify)
        fs:SetWordWrap(false)
        cells[col.key] = fs
        x = x + col.width + 6
    end
    return cells
end

local function RowTooltip(self)
    local data = self.data
    if not data then return end
    local recipe = data.recipe
    GameTooltip:SetOwner(self, "ANCHOR_RIGHT")
    if data.kind == "sell" then
        local unit = db.prices[data.itemID]
        GameTooltip:AddLine(ItemName(data.itemID))
        GameTooltip:AddDoubleLine(format("%d in your bags", data.count),
            unit and (Money(unit) .. " each") or "none listed", 1, 1, 1, 1, 1, 1)
        GameTooltip:AddLine("No recipe you know turns these into more gold than listing them.", 0.7, 0.7, 0.7, true)
        GameTooltip:Show()
        return
    elseif data.kind == "craft" then
        GameTooltip:AddLine(format("%d x %s", data.crafts, recipe.name))
        GameTooltip:AddLine(format("Makes %s x %s", recipe.qty * data.crafts, ItemName(recipe.out)), 1, 1, 1)
        GameTooltip:AddLine(" ")
        for itemID, count in pairs(data.uses) do
            local unit = db.prices[itemID]
            GameTooltip:AddDoubleLine(format("%d x %s", count, ItemName(itemID)),
                unit and (Money(unit) .. " each") or "no price", 1, 1, 1, 1, 1, 1)
        end
        for itemID, count in pairs(data.buys) do
            GameTooltip:AddDoubleLine(format("%d x %s", count, ItemName(itemID)),
                format("buy, %s each", Money(db.vendor[itemID])), 1, 1, 1, 0.7, 0.7, 0.7)
        end
        GameTooltip:AddLine(" ")
        GameTooltip:AddDoubleLine("Those herbs sold raw", Money(data.raw), 1, 0.82, 0, 1, 1, 1)
        GameTooltip:AddDoubleLine("Brewed and sold", Money(data.value), 1, 0.82, 0, 1, 1, 1)
        GameTooltip:Show()
        return
    end
    GameTooltip:AddLine(recipe.name)
    GameTooltip:AddLine(format("Makes %s x %s", recipe.qty, ItemName(recipe.out)), 1, 1, 1)
    GameTooltip:AddLine(" ")
    local seen = { [recipe.out] = true }
    for _, slot in ipairs(recipe.slots) do
        local itemID, price, source = SlotBest(slot, seen)
        local left = format("%s x %s", slot.qty, ItemName(itemID))
        if price then
            GameTooltip:AddDoubleLine(left, format("%s each (%s)", Money(price), source), 1, 1, 1, 1, 1, 1)
        else
            GameTooltip:AddDoubleLine(left, "no price", 1, 1, 1, 1, 0.3, 0.3)
        end
    end
    GameTooltip:AddLine(" ")
    local unit = db.prices[recipe.out]
    GameTooltip:AddDoubleLine("Cheapest on AH", unit and (Money(unit) .. " each") or "none listed", 1, 0.82, 0, 1, 1, 1)
    GameTooltip:Show()
end

local function CreateWindow()
    local f = CreateFrame("Frame", "WhatToBrewFrame", UIParent, "BasicFrameTemplateWithInset")
    f:SetSize(620, 460)
    f:SetPoint("CENTER")
    f:SetFrameStrata("HIGH")
    f:SetMovable(true)
    f:EnableMouse(true)
    f:RegisterForDrag("LeftButton")
    f:SetScript("OnDragStart", f.StartMoving)
    f:SetScript("OnDragStop", f.StopMovingOrSizing)
    f:SetClampedToScreen(true)
    tinsert(UISpecialFrames, "WhatToBrewFrame")
    if f.TitleText then f.TitleText:SetText("What To Brew") end

    f.scan = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
    f.scan:SetSize(80, 22)
    f.scan:SetPoint("TOPLEFT", 12, -30)
    f.scan:SetText("Scan")
    f.scan:SetScript("OnClick", function() StartScan(false) end)

    f.scanAll = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
    f.scanAll:SetSize(80, 22)
    f.scanAll:SetPoint("LEFT", f.scan, "RIGHT", 4, 0)
    f.scanAll:SetText("Scan all")
    f.scanAll:SetScript("OnClick", function() StartScan(true) end)

    f.export = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
    f.export:SetSize(70, 22)
    f.export:SetPoint("LEFT", f.scanAll, "RIGHT", 4, 0)
    f.export:SetText("Export")
    f.export:SetScript("OnClick", ShowExport)

    f.status = f:CreateFontString(nil, "OVERLAY", "GameFontHighlightSmall")
    f.status:SetPoint("BOTTOMLEFT", f, "BOTTOMLEFT", 14, 12)
    f.status:SetPoint("RIGHT", f, "RIGHT", -14, 0)

    f.view = CreateFrame("Button", nil, f, "UIPanelButtonTemplate")
    f.view:SetSize(90, 22)
    f.view:SetPoint("LEFT", f.export, "RIGHT", 4, 0)
    f.view:SetScript("OnClick", function()
        db.view = db.view ~= "herbs" and "herbs" or nil
        Refresh()
    end)
    f.status:SetJustifyH("LEFT")
    f.status:SetWordWrap(false)

    local header = CreateFrame("Frame", nil, f)
    header:SetPoint("TOPLEFT", 12, -58)
    header:SetSize(570, ROW_HEIGHT)
    f.titles = MakeCells(header, "GameFontNormalSmall")

    local scroll = CreateFrame("ScrollFrame", nil, f, "UIPanelScrollFrameTemplate")
    scroll:SetPoint("TOPLEFT", header, "BOTTOMLEFT", 0, -2)
    scroll:SetPoint("BOTTOMRIGHT", f, "BOTTOMRIGHT", -32, 30)
    f.content = CreateFrame("Frame", nil, scroll)
    f.content:SetSize(570, 1)
    scroll:SetScrollChild(f.content)

    f.empty = f:CreateFontString(nil, "OVERLAY", "GameFontDisable")
    f.empty:SetPoint("CENTER", scroll)

    f.rows = {}
    f:SetScript("OnShow", function() Refresh() end)
    f:Hide()
    return f
end

local function GetRow(i)
    local row = window.rows[i]
    if not row then
        row = CreateFrame("Button", nil, window.content)
        row:SetSize(570, ROW_HEIGHT)
        row:SetPoint("TOPLEFT", 0, -(i - 1) * ROW_HEIGHT)
        row.cells = MakeCells(row, "GameFontHighlightSmall")
        local hl = row:CreateTexture(nil, "HIGHLIGHT")
        hl:SetAllPoints()
        hl:SetColorTexture(1, 1, 1, 0.08)
        row:SetScript("OnEnter", RowTooltip)
        row:SetScript("OnLeave", GameTooltip_Hide)
        window.rows[i] = row
    end
    return row
end

local function FillRecipeRow(cells, data)
    cells.name:SetText(data.recipe.name)
    cells.cost:SetText(data.cost and Money(data.cost) or "|cffff5555missing|r")
    cells.sell:SetText(data.revenue and Money(data.revenue) or "|cff808080none listed|r")
    if data.profit then
        local color = data.profit >= 0 and "|cff40ff40" or "|cffff5555"
        cells.profit:SetText(Money(data.profit))
        cells.margin:SetText(data.cost > 0 and format("%s%d%%|r", color, math.floor(data.profit / data.cost * 100 + 0.5)) or "")
    else
        cells.profit:SetText("|cff808080--|r")
        cells.margin:SetText("")
    end
end

local function FillHerbRow(cells, data)
    if data.kind == "craft" then
        cells.name:SetText(format("|cff40ff40Brew|r %d x %s", data.crafts, data.recipe.name))
        cells.cost:SetText(Money(data.raw))
        cells.sell:SetText(Money(data.value))
        cells.profit:SetText("|cff40ff40+|r" .. Money(data.gain))
        cells.margin:SetText(data.raw > 0 and format("|cff40ff40+%d%%|r", math.floor(data.gain / data.raw * 100 + 0.5)) or "")
    else
        cells.name:SetText(format("|cffffd100Sell|r %d x %s", data.count, ItemName(data.itemID)))
        cells.cost:SetText(data.value and Money(data.value) or "|cff808080none listed|r")
        cells.sell:SetText("")
        cells.profit:SetText("")
        cells.margin:SetText("")
    end
end

function Refresh()
    local herbs = db.view == "herbs"
    window.view:SetText(herbs and "Recipes" or "My herbs")
    for _, col in ipairs(COLUMNS) do window.titles[col.key]:SetText(herbs and col.herbs or col.title) end

    local rows, totals
    if herbs then
        rows, totals = BuildHerbRows()
    else
        rows = BuildRows()
    end
    local fill = herbs and FillHerbRow or FillRecipeRow
    for i, data in ipairs(rows) do
        local row = GetRow(i)
        row.data = data
        fill(row.cells, data)
        row:Show()
    end
    for i = #rows + 1, #window.rows do window.rows[i]:Hide() end
    window.content:SetHeight(math.max(1, #rows * ROW_HEIGHT))
    window.empty:SetText(herbs and "No herbs or recipe reagents in your bags."
        or "Open your Alchemy window once so your recipes can be read.")
    window.empty:SetShown(#rows == 0)
    if scan then return end
    if not db.scanTime then
        SetStatus("No prices yet: open the auction house and press Scan.")
    elseif herbs then
        SetStatus(format("Brew, then sell the rest: %s. Sell it all raw: %s. Brewing adds %s. Scanned %s.",
            Money(totals.brewed + totals.sold), Money(totals.raw),
            Money(totals.brewed + totals.sold - totals.raw), Age(db.scanTime)))
    else
        SetStatus(format("%d recipes. Prices scanned %s. Hover a row for the reagent breakdown.", #rows, Age(db.scanTime)))
    end
end

local function Toggle()
    if not window then window = CreateWindow() end
    window:SetShown(not window:IsShown())
end

local events = CreateFrame("Frame")
events:RegisterEvent("ADDON_LOADED")
events:SetScript("OnEvent", function(self, event, arg1)
    if event == "ADDON_LOADED" then
        if arg1 ~= "WhatToBrew" then return end
        WhatToBrewDB = WhatToBrewDB or {}
        db = WhatToBrewDB
        db.recipes = db.recipes or {}
        db.prices = db.prices or {}
        db.vendor = db.vendor or {}
        self:UnregisterEvent("ADDON_LOADED")
        for _, e in ipairs({
            "TRADE_SKILL_SHOW", "TRADE_SKILL_LIST_UPDATE", "TRADE_SKILL_DATA_SOURCE_CHANGED", "NEW_RECIPE_LEARNED",
            "AUCTION_HOUSE_SHOW", "AUCTION_HOUSE_CLOSED",
            "COMMODITY_SEARCH_RESULTS_UPDATED", "ITEM_SEARCH_RESULTS_UPDATED",
            "AUCTION_HOUSE_BROWSE_RESULTS_UPDATED", "AUCTION_HOUSE_BROWSE_RESULTS_ADDED",
            "AUCTION_HOUSE_BROWSE_FAILURE",
            "MERCHANT_SHOW", "BAG_UPDATE_DELAYED",
        }) do
            pcall(self.RegisterEvent, self, e)
        end
    elseif event == "AUCTION_HOUSE_SHOW" then
        ahOpen = true
    elseif event == "AUCTION_HOUSE_CLOSED" then
        ahOpen = false
        StopScan(false)
    elseif event == "COMMODITY_SEARCH_RESULTS_UPDATED" then
        OnCommodityResults(arg1)
    elseif event == "ITEM_SEARCH_RESULTS_UPDATED" then
        OnItemResults(arg1)
    elseif event == "AUCTION_HOUSE_BROWSE_RESULTS_UPDATED" then
        OnBrowseResults()
    elseif event == "AUCTION_HOUSE_BROWSE_RESULTS_ADDED" then
        OnBrowseResults(arg1)
    elseif event == "AUCTION_HOUSE_BROWSE_FAILURE" then
        if scan and scan.phase == "browse" then FinishBrowse(false) end
    elseif event == "MERCHANT_SHOW" then
        LearnVendorPrices()
    elseif event == "BAG_UPDATE_DELAYED" then
        if window and window:IsShown() and db.view == "herbs" and not scan then Refresh() end
    else
        CaptureRecipes()
    end
end)

